import LocalProtocol from "local-protocol";

const client = new LocalProtocol();

const request = await client.requests.create({
  id: "req_demo_123",
  nonce: "nonce_demo_123",
  pickup_location: {
    coordinates: { latitude: 37.7751, longitude: -122.4193 },
  },
  dropoff_location: {
    coordinates: { latitude: 37.7875, longitude: -122.4073 },
  },
  pickup_time: "2026-02-10T17:00:00Z",
  dropoff_time: "2026-02-10T17:30:00Z",
});

console.log(request.id);

import LocalProtocol from "local-protocol";

const client = new LocalProtocol();

const quote = await client.requests.quotes.create("req_demo_123", {
  id: "quote_demo_123",
  nonce: "nonce_quote_123",
  price: 1299,
  currency: "USD",
  pickup_location: {
    coordinates: { latitude: 37.7751, longitude: -122.4193 },
  },
  dropoff_location: {
    coordinates: { latitude: 37.7875, longitude: -122.4073 },
  },
  pickup_estimate: "2026-02-10T17:08:00Z",
  dropoff_estimate: "2026-02-10T17:30:00Z",
  payment: {
    instruments: [
      {
        id: "pi_demo_123",
        handler_id: "com.localprotocol.evm_auth_capture_escrow",
        type: "evm_auth_capture_escrow",
      },
    ],
  },
});

console.log(quote.id);

import LocalProtocol from "local-protocol";

const client = new LocalProtocol();

const delivery = await client.deliveries.create({
  request_id: "req_demo_123",
  quote_id: "quote_demo_123",
  nonce: "nonce_delivery_123",
  event_vocabulary: "xyz.localprotocol.delivery.courier@2026-01-30",
});

console.log(delivery.id);
